"""Verify the two reports generated by the README walkthrough."""
import json
import sys
from pathlib import Path

import fitz
from pptx import Presentation


def inspect(folder, expected, series):
    for filename in ("outline.md", "report-inputs.json", "report.pptx", "report.pdf", "check_report.json"):
        assert (folder / filename).stat().st_size > 0, filename
    checks = json.loads((folder / "check_report.json").read_text(encoding="utf-8"))
    assert checks["status"] == "pass" and checks["issues"] == [], checks
    assert checks["expected"] == expected, checks["expected"]
    deck = Presentation(folder / "report.pptx")
    assert len(deck.slides) == expected["slides"]
    charts = [shape.chart for slide in deck.slides for shape in slide.shapes if shape.has_chart]
    if series:
        assert len(charts) == 1
        assert list(charts[0].series[0].values) == series
    else:
        assert not charts
    with fitz.open(folder / "report.pdf") as pdf:
        assert len(pdf) == expected["slides"]
        if not expected["data_available"]:
            assert "Data belum tersedia" in pdf[0].get_text()
            assert "judul tercatat" not in pdf[0].get_text()


def main():
    if len(sys.argv) != 3:
        raise SystemExit("usage: python tests/smoke.py KRAKATAU_FOLDER OUT_OF_COVERAGE_FOLDER")
    pilot, missing = map(Path, sys.argv[1:])
    inputs = json.loads((pilot / "report-inputs.json").read_text(encoding="utf-8"))
    series = [day["count"] for day in inputs["facts"]["daily_trend"]]
    assert len(series) == 14 and sum(series) == 1976 and max(series) == 733
    inspect(pilot, {"slides": 4, "data_available": True, "total": 1976,
                    "peak": {"at": "2026-09-06", "count": 733}, "daily_chart_points": 14, "headline_links": 3},
            series)
    inspect(missing, {"slides": 1, "data_available": False, "total": None,
                      "peak": None, "daily_chart_points": 0, "headline_links": 0}, [])
    print("PASS: Krakatau has four checked slides and the coverage case has one checked slide.")


if __name__ == "__main__":
    main()
